const D = { energy: .62, scale: 1, speed: 1, density: .5, sharp: .55, hue: 212, x: .5, y: .5, style: 'lamellae', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Chaotic advection — the alternating sine flow (a continuous baker's map) ------------
// Half a period shears in x by sin(2*pi*y); the next half shears in y by sin(2*pi*x). Neither
// map alone does anything interesting, but ALTERNATED they compose into a Smale horseshoe:
// dye is stretched and folded, striations thin like e^(lambda*t), and yet elliptic KAM islands
// sit inside the chaos and never mix at all.
//
// The trick that makes this renderable: each half-step is an EXACT closed-form shear (the
// shear velocity depends only on the coordinate the shear does not move), so it inverts in
// closed form. Rather than advect a dye field forward and watch numerical diffusion smear the
// striations into grey mush, every pixel walks the map BACKWARD N half-steps and reads the
// initial dye analytically. Zero diffusion — the lamellae stay razor sharp forever, and the
// only cutoff is the pixel grid itself (which is exactly the physical Batchelor scale).
//
// The phases drift on incommensurate rates (the "random-phase sine flow"). That is not
// decoration: with fixed phases the backward composition at t and t+period is the SAME map,
// so the frame would be byte-identical one period later.
// -----------------------------------------------------------------------------------------
const TAU = 6.283185307;
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.C = new Float32Array(N); S.AC = new Float32Array(N);
}
const C = S.C, AC = S.AC;

const sd = P.seed | 0;
function fr(i) { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); }

const tt = K.t;
const L = BW / BH;                 // torus is [0,L] x [0,1] — square in PIXELS, so no stretch
const KX = 2;                      // shear cells across the frame
const sph = fr(3) * TAU, sph2 = fr(7) * TAU;

// energy IS the Lyapunov exponent: the shear displacement per half step. Low = regular flow
// with fat islands, high = global chaos that mixes everything.
const amp = 0.35 + P.energy * 1.15;
const h = 1.45 / (0.35 + P.speed * 0.65);         // half-period, seconds
const NST = 6 + Math.round(P.density * 18);        // striation count / how far back we look

const m0 = Math.floor(tt / h);
const fr0 = tt / h - m0;

// ---- phases + amplitudes are per-half-step, not per-pixel: precompute the whole history ----
if (!S.PH || S.PH.length < NST + 2) { S.PH = new Float64Array(64); S.AM = new Float64Array(64); }
const PH = S.PH, AM = S.AM;
for (let k = 0; k <= NST; k++) {
  const m = m0 - k;
  PH[k] = (m & 1)
    ? 0.29 * Math.cos(m * 0.1873 + 0.4) + 0.21 * Math.sin(m * 0.1117 + 2.2) + sph2
    : 0.31 * Math.sin(m * 0.2417 + 1.7) + 0.19 * Math.sin(m * 0.0913) + sph;
  AM[k] = amp * (0.85 + 0.30 * Math.sin(m * 0.0731 + 0.9));
}

// ---- true optical zoom: the buffer covers a sub-rectangle of the torus, so magnifying
// resolves FINER striations instead of enlarging pixels. The torus wraps, so any x/y pans. ----
const z = Math.max(1, P.scale);
const spanX = L / z, spanY = 1 / z;
const ox = P.x * L - spanX * 0.5 + 0.021 * Math.sin(tt * 0.047);
const oy = P.y - spanY * 0.5 + 0.017 * Math.cos(tt * 0.039 + 1.1);

const shp = 1.2 + P.sharp * 5.5;
const kxl = KX / L;

for (let j = 0; j < BH; j++) {
  const Y0 = oy + (j + 0.5) / BH * spanY;
  for (let i = 0; i < BW; i++) {
    let X = ox + (i + 0.5) / BW * spanX, Y = Y0;
    // undo the partially-elapsed current half-step, then whole ones back through the history
    if (m0 & 1) Y -= fr0 * AM[0] * Math.sin(TAU * (X * kxl + PH[0]));
    else        X -= fr0 * AM[0] * Math.sin(TAU * (Y + PH[0]));
    for (let k = 1; k <= NST; k++) {
      if ((m0 - k) & 1) Y -= AM[k] * Math.sin(TAU * (X * kxl + PH[k]));
      else              X -= AM[k] * Math.sin(TAU * (Y + PH[k]));
    }
    // read the initial dye analytically at the pre-image
    const yw = Y - Math.floor(Y);
    const xw = X / L - Math.floor(X / L);
    const s1 = Math.sin(TAU * (yw + 0.12));
    const s2 = Math.sin(TAU * (xw * 0.5 + 0.31));
    const p = j * BW + i;
    C[p] = 0.5 + 0.5 * Math.tanh(s1 * shp);      // the two pigments
    AC[p] = 0.5 + 0.5 * Math.tanh(s2 * shp * 0.45);
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + Math.sin(tt * 0.019) * 9 + sec * 6) % 360 + 360) % 360;
function pal(m, sp2, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(TAU * (m + hr)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2 * 2))];
}
const cA = pal(0.02, 0.14, 0.0), cB = pal(0.46, 0.14, 0.0), cC = pal(0.72, 0.20, 0.0);
const en = P.energy;
const glow = (0.35 + en * 0.9) * (0.85 + A.bass * 0.45 + K.swell * 0.12);

for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1, p = jc + i;
    const c = C[p], a = AC[p];
    // |grad c| is the striation density — high in the chaotic sea, ~0 inside a KAM island
    const gx = (C[jc + ip] - C[jc + im]) * 0.5, gy = (C[jp + i] - C[jm + i]) * 0.5;
    const gm = Math.sqrt(gx * gx + gy * gy);
    const mix = Math.tanh(gm * 3.4);
    let r, gg, b;
    if (style === 'mineral') {
      // banded gneiss / agate: matte strata, no glow, stone grain
      const gr = (fr(i * 3.1 + j * 7.7) - 0.5) * 0.06;
      const band = c * 0.72 + a * 0.28;
      const v = 0.20 + band * 0.44 + gr;
      r = v * (0.86 + 0.30 * band); gg = v * (0.74 + 0.20 * band); b = v * (0.58 + 0.10 * band);
      r += mix * 0.05; gg += mix * 0.035; b += mix * 0.02;
    } else if (style === 'mixing_index') {
      // abstracted: forget the dye, show only WHERE the fluid is mixing. Islands go dark.
      const m = Math.min(1, mix * (0.6 + en * 1.1) + 0.05);
      const cc = pal(0.10 + m * 0.62, 0.28, 0.0);
      const v = 0.10 + m * 0.72;
      r = v * (0.35 + cc[0] * 0.9); gg = v * (0.35 + cc[1] * 0.9); b = v * (0.40 + cc[2] * 0.9);
    } else if (style === 'ink_marble') {
      // sumi lamellae on bone paper — the ink is the mass, the paper is the ground
      const gr = (fr(i * 5.3 + j * 2.9) - 0.5) * 0.07;
      const v = 0.86 - c * 0.70 + gr - mix * 0.10;
      r = v * 0.99; gg = v * 0.975; b = v * 0.93;
    } else if (style === 'spectral') {
      // iridescent oil film: the dye phase drives a full cosine spectrum
      const ph = c * 0.55 + a * 0.28 + mix * 0.14;
      const cc = pal(ph, 0.33, 0.0);
      const v = 0.24 + 0.34 * (0.4 + mix * 0.6);
      r = v * (0.30 + cc[0] * 1.25); gg = v * (0.30 + cc[1] * 1.25); b = v * (0.32 + cc[2] * 1.25);
    } else {                                   // lamellae (default)
      // two pigments in a dark bath; the interfaces between them catch the light
      const bl = 0.26 + a * 0.13;
      r = (cA[0] * (1 - c) + cB[0] * c) * bl + cC[0] * 0.05;
      gg = (cA[1] * (1 - c) + cB[1] * c) * bl + cC[1] * 0.05;
      b = (cA[2] * (1 - c) + cB[2] * c) * bl + cC[2] * 0.07;
      const ed = mix * glow * 0.42;
      r += ed * 1.0; gg += ed * 0.94; b += ed * 0.78;
    }
    const o = 4 * p;
    px[o] = r < 0 ? 0 : (r > 1 ? 255 : r * 255);
    px[o + 1] = gg < 0 ? 0 : (gg > 1 ? 255 : gg * 255);
    px[o + 2] = b < 0 ? 0 : (b > 1 ? 255 : b * 255);
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
